using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
class BeamDeflectionForm:DesignSheetForm {
 readonly DataGridView groups=new DataGridView{Width=1050,Height=290,Tag="FullWidth",AllowUserToAddRows=true,AllowUserToDeleteRows=true,MultiSelect=true,RowHeadersVisible=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None};
 readonly DataGridView output=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
 TextBox coordinates,members,displacements;readonly List<BeamDeflectionResult> latest=new List<BeamDeflectionResult>();
 public BeamDeflectionForm():base("Beam Deflection Check","Beam-Deflection"){
 var input=Section("Physical beam groups","Group collinear STAAD member segments into one physical span. Intermediate analysis nodes are not automatically supports. Split at real supports. Deflection is measured relative to the displaced support chord, per selected service load case. Nodal results alone do not establish an unsampled between-node maximum.");Choice(input,"Vertical","Global displacement component",new[]{"Y","Z","X"});Toggle(input,"ServiceBasis","Results match the model and service/unfactored load basis",false);Toggle(input,"SupportsVerified","The two endpoints are the actual span supports",false);
 foreach(string name in new[]{"Beam ID","Member IDs (comma separated)","Support A (blank=endpoint)","Support B (blank=endpoint)","Service load cases (blank=all)","Limit L/n","Span m","Max sampled mm","Status"})groups.Columns.Add(name,name);for(int i=6;i<groups.ColumnCount;i++)groups.Columns[i].ReadOnly=true;groups.Columns[0].Width=120;groups.Columns[1].Width=220;groups.Columns[4].Width=220;groups.Columns[8].Width=420;groups.DefaultValuesNeeded+=(s,e)=>e.Row.Cells[5].Value="360";GridAppearance.Apply(groups);RowDeleteAffordance.Attach(groups);GridEditHistory.Configure(groups,()=>Restoring,value=>Restoring=value,()=>{});input.Controls.Add(groups);var edits=new FlowLayoutPanel{Width=1050,Height=45,Tag="FullWidth"};GridEditHistory.AddCommands(this,edits);input.Controls.Add(edits);
 var geometry=Section("STAAD model geometry","Import the matching .STD model or expanded coordinate/incidence tables. Geometry units and displacement units are separate. REPEAT-generated geometry must be exported as expanded coordinates. Spreadsheet imports read cached cell data; macros are not executed.");Choice(geometry,"GeometryUnit","Coordinate unit",new[]{"m","mm","cm","ft","in"});coordinates=TableInput(geometry,"Coordinates","Node coordinates (Node, X, Y, Z)");members=TableInput(geometry,"Members","Member incidences (Member, StartNode, EndNode)");var geometryActions=new FlowLayoutPanel{Width=1050,Height=48,Tag="FullWidth"};Action(geometryActions,"Import STD model",ImportModel);Action(geometryActions,"Import coordinates table",()=>ImportTable(coordinates,"coordinates"));Action(geometryActions,"Import member incidences",()=>ImportTable(members,"members"));geometry.Controls.Add(geometryActions);
 var results=Section("STAAD displacements","STAAD Post Processing > Node Displacements: copy/export all selected load cases, including both support nodes and intermediate nodes. Include headers. ANL import reads JOINT DISPLACEMENTS and echoed geometry when available; otherwise import matching model geometry separately. Check translation units independently of rotation units.");Choice(results,"DisplacementUnit","Translation unit",new[]{"mm","cm","m","in","ft"});displacements=TableInput(results,"Displacements","Node displacement results (Node, L/C, X/Y/Z translation)");var actions=new FlowLayoutPanel{Width=1050,Height=48,Tag="FullWidth"};Action(actions,"Paste displacement table",()=>{if(Clipboard.ContainsText())displacements.Text=Clipboard.GetText();});Action(actions,"Import CSV / Excel results",()=>ImportTable(displacements,"displacements"));Action(actions,"Import ANL output",ImportAnl);results.Controls.Add(actions);
 var page=new TabPage("Deflection results");foreach(string name in new[]{"Beam","Load case","Support A","Support B","Span m","Max sampled |δ| mm","Limit mm","At station m","Node","Decision"})output.Columns.Add(name,name);output.Columns[9].FillWeight=260;GridAppearance.Apply(output);page.Controls.Add(output);AddResultPage(page);}
 TextBox TableInput(FlowLayoutPanel panel,string key,string title){panel.Controls.Add(new Label{Text=title,Width=1050,Height=28,Tag="FullWidth",Font=ModernUi.Strong});var text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1050,Height=170,Tag="FullWidth",Font=new Font("Consolas",9)};Inputs.Add(key,text);panel.Controls.Add(text);return text;}
 void Action(FlowLayoutPanel panel,string caption,System.Action action){var button=new Button{Text=caption,AutoSize=true};button.Click+=(s,e)=>{try{action();}catch(Exception error){MessageBox.Show(this,error.Message,caption);}};panel.Controls.Add(button);}
 BeamDeflectionData Data(){var data=new BeamDeflectionData();StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);StaadDisplacements.Displacements(data,displacements.Text,Value("DisplacementUnit"));return data;}
 static string NodesText(BeamDeflectionData data,double unit){return "Node\tX\tY\tZ\r\n"+string.Join("\r\n",data.Nodes.Values.OrderBy(n=>n.Id).Select(n=>n.Id+"\t"+N(n.X/unit)+"\t"+N(n.Y/unit)+"\t"+N(n.Z/unit)));}
 static string MembersText(BeamDeflectionData data){return "Member\tStartNode\tEndNode\r\n"+string.Join("\r\n",data.Members.Values.OrderBy(m=>m.Id).Select(m=>m.Id+"\t"+m.A+"\t"+m.B));}
 static string ResultText(BeamDeflectionData data,double unit){return "Node\tL/C\tX\tY\tZ\r\n"+string.Join("\r\n",data.Displacements.Select(d=>d.Node+"\t"+d.Case+"\t"+N(d.X/unit)+"\t"+N(d.Y/unit)+"\t"+N(d.Z/unit)));}
 void ImportModel(){using(var dialog=new OpenFileDialog{Filter="STAAD model|*.std;*.txt"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();StaadDisplacements.Model(data,File.ReadAllText(dialog.FileName),Value("GeometryUnit"));if(data.Nodes.Count==0||data.Members.Count==0)throw new Exception("No complete expanded model geometry found.");coordinates.Text=NodesText(data,StaadDisplacements.Unit(Value("GeometryUnit")));members.Text=MembersText(data);displacements.Clear();if(data.ZUp)Inputs["Vertical"].Text="Z";}}
 void ImportAnl(){using(var dialog=new OpenFileDialog{Filter="STAAD analysis output|*.anl;*.txt"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();StaadDisplacements.Anl(data,File.ReadAllText(dialog.FileName),Value("GeometryUnit"),Value("DisplacementUnit"));if(data.Nodes.Count>0&&data.Members.Count>0){coordinates.Text=NodesText(data,StaadDisplacements.Unit(Value("GeometryUnit")));members.Text=MembersText(data);if(data.ZUp)Inputs["Vertical"].Text="Z";}displacements.Text=ResultText(data,StaadDisplacements.Unit(Value("DisplacementUnit")));}}
 void ImportTable(TextBox target,string kind){using(var dialog=new OpenFileDialog{Filter="STAAD tables|*.csv;*.tsv;*.txt;*.xlsx;*.xlsm"})if(dialog.ShowDialog(this)==DialogResult.OK){var candidates=Path.GetExtension(dialog.FileName).Equals(".xlsx",StringComparison.OrdinalIgnoreCase)||Path.GetExtension(dialog.FileName).Equals(".xlsm",StringComparison.OrdinalIgnoreCase)?StaadSpreadsheet.Tables(dialog.FileName).Values.ToList():new List<string>{File.ReadAllText(dialog.FileName)};Exception last=null;foreach(string text in candidates){try{var data=new BeamDeflectionData();if(kind=="coordinates")StaadDisplacements.Coordinates(data,text,Value("GeometryUnit"));else if(kind=="members")StaadDisplacements.Members(data,text);else StaadDisplacements.Displacements(data,text,Value("DisplacementUnit"));target.Text=text;return;}catch(Exception error){last=error;}}throw new Exception("No usable "+kind+" table found. "+(last==null?"":last.Message));}}
 static string N(double n){return n.ToString("0.#########",CultureInfo.InvariantCulture);}static string Cell(DataGridViewRow row,int col){return Convert.ToString(row.Cells[col].Value,CultureInfo.InvariantCulture).Trim();}
 void Evaluate(){groups.EndEdit();var data=Data();latest.Clear();output.Rows.Clear();var errors=new List<string>();foreach(DataGridViewRow row in groups.Rows){if(row.IsNewRow||Cell(row,1)=="")continue;try{var input=new PhysicalBeamInput{Name=Cell(row,0)==""?"Beam "+(row.Index+1):Cell(row,0),Members=Cell(row,1),Start=Cell(row,2)==""?0:StaadDisplacements.Id(Cell(row,2)),End=Cell(row,3)==""?0:StaadDisplacements.Id(Cell(row,3)),Cases=Cell(row,4),LimitRatio=Cell(row,5)==""?360:StaadDisplacements.Number(Cell(row,5)),Vertical=Value("Vertical"),ServiceBasis=((CheckBox)Inputs["ServiceBasis"]).Checked,SupportsVerified=((CheckBox)Inputs["SupportsVerified"]).Checked};var values=BeamDeflection.Calculate(data,input);latest.AddRange(values);row.Cells[6].Value=values[0].Span;row.Cells[7].Value=values.Max(v=>v.MaximumMm);row.Cells[8].Value=values.Any(v=>v.MaximumMm>v.LimitMm)?"Sampled limit exceeded":"Review nodal sampling / support and load basis";foreach(var value in values)output.Rows.Add(value.Beam,value.Case,value.StartNode,value.EndNode,N(value.Span),N(value.MaximumMm),N(value.LimitMm),N(value.At),value.GoverningNode,value.Status);}catch(Exception error){row.Cells[8].Value=error.Message;errors.Add("Row "+(row.Index+1)+": "+error.Message);}}if(errors.Count>0)throw new Exception(string.Join("\r\n",errors));if(latest.Count==0)throw new Exception("Enter at least one beam group with its member IDs.");}
 protected override string BuildReport(){Evaluate();var b=new StringBuilder("BEAM DEFLECTION CHECK\r\n");b.AppendLine("Relative support-chord displacement per physical beam and load case.");b.AppendLine("δrel(s) = u(s) − [uA + (uB − uA) s/L]. Geometry in m; result translations in mm.");foreach(var value in latest){b.AppendLine(value.Beam+" | Case "+value.Case+" | L="+N(value.Span)+"m | max sampled="+N(value.MaximumMm)+"mm | limit="+N(value.LimitMm)+"mm | "+value.Status);b.AppendLine("Node | Station m | Absolute mm | Chord mm | Relative mm");foreach(var station in value.Stations)b.AppendLine(station.Node+" | "+N(station.Station)+" | "+N(station.Absolute)+" | "+N(station.Chord)+" | "+N(station.Relative));}b.AppendLine("Nodal sampling does not establish the between-node maximum. Use STAAD member/section displacement results to verify unsampled extrema. A within-limit nodal result is not an unqualified design PASS.");return b.ToString();}
 protected override EngineeringReport BuildEngineeringReport(){Evaluate();var project=ProjectInfoStore.Read();var report=ProfessionalReport.Create("Beam deflection check",project.Name,project.Location,project.Office);report.Subtitle="Physical member grouping · intermediate nodes · support-relative displacement";report.Section("Basis").Equation("δrel(s) = u(s) − [uA + (uB − uA)s/L]\nδlimit = L/n");foreach(var value in latest){var section=report.Section(value.Beam+" / load case "+value.Case);section.Table(new[]{"Span m","Max sampled mm","Limit mm","Governing station m","Node"},new[]{new[]{N(value.Span),N(value.MaximumMm),N(value.LimitMm),N(value.At),value.GoverningNode.ToString()}});section.Note(value.Status);section.Table(new[]{"Node","Station m","Absolute mm","Chord mm","Relative mm"},value.Stations.Select(s=>new[]{s.Node.ToString(),N(s.Station),N(s.Absolute),N(s.Chord),N(s.Relative)}));}report.Section("Sampling and engineering review").Note("Intermediate analysis nodes remain part of one physical beam; they are not assumed supports. Check service-load basis and the applicable project limit. Nodal data alone cannot prove the unsampled between-node maximum.");return report;}
 protected override CalculationDocument BuildDocument(){BuildReport();var document=new CalculationDocument("Beam deflection check");document.ReportFile=BuildEngineeringReport();string vertical=Value("Vertical");foreach(var value in latest){for(int offset=0;offset<value.Stations.Count;offset+=20){var rows=value.Stations.Skip(offset).Take(20).Select(s=>new[]{s.Node.ToString(),N(s.Station),N(s.Absolute),N(s.Chord),N(s.Relative)}).ToList();var captured=value;document.Sheets.Add(g=>{CalculationDocument.Section(g,captured.Beam+" / CASE "+captured.Case,130);CalculationDocument.Text(g,"Supports "+captured.StartNode+" → "+captured.EndNode+"; L="+N(captured.Span)+"m; sampled max="+N(captured.MaximumMm)+"mm; limit="+N(captured.LimitMm)+"mm\r\n"+captured.Status,36,176,523,70,10,true);CalculationDocument.Text(g,"δrel(s) = u(s) − [uA + (uB − uA)s/L]. Component: global "+Value("Vertical")+".\r\nNodal sampling does not establish a between-node maximum.",36,252,523,52,9);CalculationDocument.Table(g,new[]{"Node","Station m","Absolute mm","Chord mm","Relative mm"},rows,316,new float[]{60,100,120,120,123},20);});}}return document;}
 protected override void WriteAdditionalState(XmlElement root){var table=root.OwnerDocument.CreateElement("BeamGroups");table.SetAttribute("version","1");root.AppendChild(table);foreach(DataGridViewRow row in groups.Rows)if(!row.IsNewRow&&Cell(row,1)!=""){var item=root.OwnerDocument.CreateElement("Beam");for(int c=0;c<6;c++)item.SetAttribute("c"+c,Cell(row,c));table.AppendChild(item);}}
 protected override void ReadAdditionalState(XmlElement root){groups.Rows.Clear();var table=root["BeamGroups"];if(table==null||table.GetAttribute("version")!="1")throw new Exception("Missing/unsupported beam group data.");foreach(XmlElement row in table.SelectNodes("Beam")){var values=Enumerable.Range(0,6).Select(c=>(object)row.GetAttribute("c"+c)).ToArray();groups.Rows.Add(values);}}
}
}
